package com.gymmind.membership.application; import com.gymmind.audit.application.AuditRecorder; import com.gymmind.audit.domain.*; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.membership.domain.model.PaymentRecord; import com.gymmind.membership.domain.repository.*; import com.gymmind.shared.error.*; import com.gymmind.shared.security.CurrentActor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.Map; @Service public class DefaultPaymentRecordService{private final PaymentRecordRepository payments;private final OrderRepository orders;private final AuditRecorder audit;public DefaultPaymentRecordService(PaymentRecordRepository p,OrderRepository o,AuditRecorder a){payments=p;orders=o;audit=a;}@Transactional public PaymentRecordView recordOfflinePayment(CurrentActor actor,RecordOfflinePaymentCommand c){if(actor==null||actor.tenantId()==null||!actor.roles().contains(RoleCode.GYM_ADMIN)||!actor.hasPermission("payment:write"))throw new BusinessException(ErrorCode.FORBIDDEN);if(c==null||c.tenantId()!=null&&!actor.tenantId().equals(c.tenantId()))throw new BusinessException(ErrorCode.FORBIDDEN);return payments.findByTenantIdAndReference(actor.tenantId(),c.reference()).map(PaymentRecordView::from).orElseGet(()->{PaymentRecord p=payments.save(PaymentRecord.create(actor.tenantId(),c.orderId(),c.amount(),c.currency(),c.reference(),c.paymentMethod()));audit.record(new AuditEvent("PAYMENT_RECORDED","PAYMENT",p.getId(),AuditResult.SUCCESS,"payment-service",Map.of()));return PaymentRecordView.from(p);});}}
